function initAudio() {
  let touchStartTime;
  let touchStartPosition;
  const MAX_TAP_DURATION = 200; // milliseconds
  const MAX_TAP_MOVEMENT = 10; // pixels

  if ('ontouchstart' in window) {
    // Mobile device
    let audioStarted = false;

    document.addEventListener('touchstart', function(e) {
      touchStartTime = Date.now();
      touchStartPosition = { x: e.touches[0].clientX, y: e.touches[0].clientY };
    });

    document.addEventListener('touchend', function(e) {
      const touchEndTime = Date.now();
      const touchEndPosition = { x: e.changedTouches[0].clientX, y: e.changedTouches[0].clientY };
      
      const touchDuration = touchEndTime - touchStartTime;
      const touchMovement = Math.sqrt(
        Math.pow(touchEndPosition.x - touchStartPosition.x, 2) +
        Math.pow(touchEndPosition.y - touchStartPosition.y, 2)
      );

      if (touchDuration < MAX_TAP_DURATION && touchMovement < MAX_TAP_MOVEMENT) {
        // This is a tap
        if (!audioStarted) {
          initAudioAndPlay();
          audioStarted = true;
        } else {
          stopSound();
          audioStarted = false;
        }
      }
    });

    // Hide start/stop buttons on touch devices
    document.getElementById('start').style.display = 'none';
    document.getElementById('stop').style.display = 'none';
  } else {
    // Desktop device
    document.getElementById('start').addEventListener('pointerdown', playSound);
    document.getElementById('stop').addEventListener('pointerdown', stopSound);
  }
}

