const lastCollisionTime = new Map();

function handleCollision(event) {
  const contact = event.contact;
  const relativeVelocity = contact.getImpactVelocityAlongNormal();
  const currentTime = world.time;
  const bodyA = event.body;
  const bodyB = event.target;

  // Only consider collisions with sufficient relative velocity
  if (Math.abs(relativeVelocity) > settings.VELOCITY_THRESHOLD) {
      const lastTimeA = lastCollisionTime.get(bodyA) || 0;
      const lastTimeB = lastCollisionTime.get(bodyB) || 0;

      // Check if enough time has passed since the last collision for these bodies
      if (currentTime - lastTimeA > settings.COOLDOWN_PERIOD && currentTime - lastTimeB > settings.COOLDOWN_PERIOD) {
          // Calculate penetration using body positions and shapes
          const distanceVec = new cannon.Vec3();
          bodyB.position.vsub(bodyA.position, distanceVec);
          const distance = distanceVec.length();
          const radiusA = bodyA.shapes[0].boundingSphereRadius;
          const radiusB = bodyB.shapes[0].boundingSphereRadius;
          const penetrationDepth = Math.max(0, radiusA + radiusB - distance);

          if (penetrationDepth > settings.COLLISION_THRESHOLD) {
            settings.count++;
            lastCollisionTime.set(bodyA, currentTime);
            lastCollisionTime.set(bodyB, currentTime);
        
            // Increase the saturation of both colliding bodies
            bodyA.saturationIncrease = settings.SATURATION_INCREASE;
            bodyB.saturationIncrease =settings.SATURATION_INCREASE;
        
            playRandomNote();
          }
      }
  }
}

function createBody(shape, material) {
  const body = new cannon.Body({
    mass: 1,
    material: material,
    shape: shape,
    collisionResponse: true
  });
  body.addEventListener("collide", handleCollision);
  body.saturationIncrease = 0; // 0 means original saturation, higher values are more saturated
  return body;
}

